def sembrar_permisos(apps, schema_editor):
    Permiso = apps.get_model("gym", "Permiso")
    Rol = apps.get_model("gym", "Rol")
    RolPermiso = apps.get_model("gym", "RolPermiso")
    Usuario = apps.get_model("gym", "Usuario")
    UsuarioRol = apps.get_model("gym", "UsuarioRol")

    permisos = {}
    for recurso in RECURSOS:
        for accion in ACCIONES:
            codigo = f"{recurso}:{accion}"
            permiso, _ = Permiso.objects.update_or_create(
                codigo=codigo,
                defaults={
                    "recurso": recurso,
                    "accion": accion,
                    "descripcion": f"{DESCRIPCION_ACCION[accion]} {recurso}",
                    "is_active": True,
                },
            )
            permisos[codigo] = permiso.pk

    for nombre_rol, politica in POLITICAS_POR_ROL.items():
        rol = Rol.objects.filter(nombre=nombre_rol).first()
        if rol is None:
            continue
        deseados = {
            permisos[f"{recurso}:{accion}"]
            for recurso, acciones in politica.items()
            for accion in acciones
        }
        existentes = set(RolPermiso.objects.filter(rol_id=rol.pk).values_list("permiso_id", flat=True))
        RolPermiso.objects.bulk_create(
            [
                RolPermiso(rol_id=rol.pk, permiso_id=permiso_id)
                for permiso_id in deseados - existentes
            ]
        )

    for usuario in Usuario.objects.only("id", "rol_id", "is_active").iterator():
        UsuarioRol.objects.get_or_create(
            usuario_id=usuario.id,
            rol_id=usuario.rol_id,
            defaults={"activo": usuario.is_active},
        )


